        if not cells:
            continue
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if len(cells) == 2 * (r1-r0+1) + 2 * (c1-c0+1) - 4:
            interior = [[g[r][c] == color for c in range(c0+1,c1)] for r in range(r0+1,r1)]
